+                <input type="password" class="form-control" @bind="_confirmPassword"
+                       @bind:after="ValidateConfirm" />
+                @if (_confirmMismatch)
+                {
+                    <div class="text-danger small mt-1">Passwords do not match.</div>
+                }
+            </div>
+
+            <button class="btn btn-warning" @onclick="UpdatePasswordAsync"
+                    disabled="@(!CanSubmit)">
+                @if (_saving) { <span class="spinner-border spinner-border-sm me-1"></span> }
+                Update Password
+            </button>
+        </div>
+    }
