toolArgs.file_text:
@using sv_cebe09599e854e64931bea66769873a7.Services
@inject ISettingsService SettingsService

@if (_loading)
{
    <div class="text-center py-5"><div class="spinner-border" role="status"></div></div>
}
else
{
    <div class="settings-section">
        <h3 class="mb-4">Appearance</h3>

        @if (!string.IsNullOrEmpty(_message))
        {
            <div class="alert alert-success alert-dismissible fade show" role="alert">
                @_message
                <button type="button" class="btn-close" @onclick="() => _message = null"></button>
            </div>
        }

        <div class="row">
            <div class="col-md-7">
                <div class="card mb-4">
                    <div class="card-body">
                        <h5 class="card-title mb-3">Theme</h5>
                        @foreach (var theme in new[] { "Light", "Dark", "System" })
                        {
                            <div class="form-check mb-2">
                                <input class="form-check-input" type="radio" name="theme"
                                       id="@($"theme-{theme}")" value="@theme"
                                       checked="@(_theme == theme)"
                                       @onchange="() => _theme = theme" />
                                <label class="form-check-label" for="@($"theme-{theme}")">@theme</label>
                            </div>
                        }
                    </div>
                </div>

                <div class="card mb-4">
                    <div class="card-body">
                        <h5 class="card-title mb-3">Font Size</h5>
                        @foreach (var size in new[] { "Small", "Medium", "Large" })
                        {
                            <div class="form-check form-check-inline">
                                <input class="form-check-input" type="radio" name="fontSize"
                                       id="@($"fs-{size}")" value="@size"
                                       checked="@(_fontSize == size)"
                                       @onchange="() => _fontSize = size" />
                                <label class="form-check-label" for="@($"fs-{size}")">@size</label>
                            </div>
                        }
                    </div>
                </div>

                <div class="card mb-4">
                    <div class="card-body">
                        <h5 class="card-title mb-3">Language</h5>
                        <select class="form-select" @bind="_language">
                            @foreach (var lang in _languages)
                            {
                                <option value="@lang">@lang</option>
                            }
                        </select>
                    </div>
                </div>

                <div class="card mb-4">
                    <div class="card-body">
                        <div class="form-check form-switch">
                            <input class="form-check-input" type="checkbox" id="compactMode" @bind="_compactMode" />
                            <label class="form-check-label" for="compactMode">
                                <strong>Compact Mode</strong>
                                <br /><small class="text-muted">Reduce spacing and padding throughout the UI</small>
                            </label>
                        </div>
                    </div>
                </div>
            </div>

            <div class="col-md-5">
                <div class="card sticky-top" style="top:1rem">
                    <div class="card-header">
                        <h5 class="mb-0">Live Preview</h5>
                    </div>
                    <div class="card-body @PreviewBgClass" style="@PreviewStyle">
                        <div class="@PreviewContainerClass">
                            <h6 class="@PreviewTextClass">Sample Heading</h6>
                            <p class="@PreviewTextClass" style="font-size: @PreviewFontSize">
                                This is how your content will look with the current settings.
                                The quick brown fox jumps over the lazy dog.
                            </p>
                            <div class="d-flex gap-2 @(_compactMode ? "mt-1" : "mt-3")">
                                <button class="btn btn-primary @(_compactMode ? "btn-sm" : "")">Primary</button>
                                <button class="btn btn-outline-secondary @(_compactMode ? "btn-sm" : "")">Secondary</button>
                            </div>
                            <div class="@(_compactMode ? "mt-1" : "mt-3")">
                                <span class="badge bg-info me-1">Tag 1</span>
                                <span class="badge bg-success me-1">Tag 2</span>
                                <span class="badge bg-warning text-dark">Tag 3</span>
                            </div>
                            <small class="@PreviewMutedClass d-block @(_compactMode ? "mt-1" : "mt-2")">
                                Language: @_language · Theme: @_theme
                            </small>
                        </div>
                    </div>
                </div>
            </div>
        </div>

        <button class="btn btn-primary" @onclick="SaveAsync" disabled="@_saving">
            @if (_saving) { <span class="spinner-border spinner-border-sm me-1"></span> }
            Save
        </button>
    </div>
}

@code {
    private bool _loading = true;
    private bool _saving;
    private string? _message;

    private string _theme = "Light";
    private string _fontSize = "Medium";
    private string _language = "English";
    private bool _compactMode;

    private readonly string[] _languages = ["English", "Spanish", "French", "German", "Japanese", "Chinese", "Portuguese"];

    protected override async Task OnInitializedAsync()
    {
        var settings = await SettingsService.GetAppearanceAsync();
        _theme = settings.Theme;
        _fontSize = settings.FontSize;
        _language = settings.Language;
        _compactMode = settings.CompactMode;
        _loading = false;
    }

    private async Task SaveAsync()
    {
        _saving = true;
        await SettingsService.SaveAppearanceAsync(new AppearanceSettings(_theme, _fontSize, _language, _compactMode));
        _message = "Appearance settings saved!";
        _saving = false;
    }

    private string PreviewFontSize => _fontSize switch
    {
        "Small" => "0.85rem",
        "Large" => "1.15rem",
        _ => "1rem"
    };

    private bool IsDark => _theme == "Dark";

    private string PreviewBgClass => IsDark ? "bg-dark" : "bg-light";
    private string PreviewTextClass => IsDark ? "text-light" : "text-dark";
    private string PreviewMutedClass => IsDark ? "text-light opacity-50" : "text-muted";
    private string PreviewContainerClass => _compactMode ? "p-1" : "p-2";
    private string PreviewStyle => $"border-radius:0.5rem;min-height:200px;font-size:{PreviewFontSize};transition:all 0.3s ease";
}

@page "/settings"
@rendermode InteractiveServer

<PageTitle>Settings</PageTitle>

<div class="settings-layout">
    <div class="settings-nav">
        <SettingsSidebar ActiveSection="@_activeSection" OnSectionChanged="s => _activeSection = s" />
    </div>
    <div class="settings-content">
        @switch (_activeSection)
        {
            case "Profile":
                <ProfileSection />
                break;
            case "Notifications":
                <NotificationsSection />
                break;
            case "Security":
                <SecuritySection />
                break;
            case "Appearance":
                <AppearanceSection />
                break;
        }
    </div>
</div>

